entries[1236807] = { ["name"] = "Gunst der Dryade", ["text"] = "Sofort\nWiederherstellung\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Rasche Heilung' zusätzliche Heilung in Höhe von 5% der verursachten Heilung, während sie aktiv war, und 25% der Heilung greift auf Verbündete in der Nähe über. Wird nach dem 5. Ziel reduziert.\n\nGleichgewicht, Wildheit, Wächter\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Sternensog' zusätzlichen Schaden in Höhe von 3% des verursachten Schadens, während sie aktiv war, und 10% des Schadens greift auf Gegner in der Nähe über. Wird nach dem 5. Ziel reduziert." }
