entries[1236822] = { ["name"] = "Blutrausch", ["text"] = "Sofort\nUnheilig\nEure Fähigkeit 'Kummer bereiten' verursacht 30% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Ghule 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen.\n\nBlut, Frost\nEure Fähigkeit 'Kummer bereiten' verursacht 50% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Tanzende Runenwaffen 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen." }
