entries[1236910] = { ["name"] = "Ewiges Geflecht", ["text"] = "150 Meter Reichweite\nSofort\nWenn die Seelenschreiberin 100 Energie erreicht, führt sie 24 Sek. lang ein Ritual durch, das mehrere Kegel verschleudert, die getroffenen Spielercharakteren 7273348 Arkanschaden zufügen.\n\nBetroffene Schicksale belegen die an sie gebundenen Spielercharakteren mit ' Verwundetes Schicksal '." }
