entries[1236938] = { ["name"] = "Statische Aufladung", ["text"] = "Sofort\nEure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 14 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%.\n(750ms Abklingzeit)" }
