entries[1236942] = { ["name"] = "Göttlicher Hammer", ["text"] = "Unbegrenzte Reichweite\nSofort\nGöttliche Hämmer wirbeln um Euch, schlagen auf Gegner in der Nähe ein und verursachen 10 Sek. lang alle 2 Sek. [ Brennender Kreuzzug : [(39.984% der Angriffskraft)% * 1.05] Strahlen / (39.984% der Angriffskraft)% Heilig]schaden.\n\nWenn aktiv, erhöht jede ausgegebene Heilige Kraft die Dauer von 'Göttlicher Hammer um 0.3 Sek. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[1236943] = { ["name"] = "Tiefer Atem", ["text"] = "100 Meter Reichweite\nSofort 2 min Abklingzeit\nAtmet tief ein, fliegt vorwärts und speit dabei geschmolzene Schlacke, die Gegnern in Eurer Bahn (400% der Zaubermacht) Vulkanschaden zufügt.\n\nEntfernt alle Bewegungsunfähigkeitseffekte. Im Flug seid Ihr immun gegen bewegungseinschränkende Effekte und Kontrollverlusteffekte. [ Sande der Zeit : Erhöht die Dauer Eurer aktiven Effekte von 'Schwarzmacht' um 5 Sek ]" }
