entries[1236989] = { ["name"] = "Mondlicht sammeln", ["text"] = "Sofort\nWildheit, Wächter, Wiederherstellung\nEin 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\nEin 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen." }
entries[1236990] = { ["name"] = "Mondlichtdurchdringung", ["text"] = "Sofort\nWildheit, Wächter, Wiederherstellung\nEin 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\nEin 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen." }
entries[1236991] = { ["name"] = "Verschlingende Leere", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr Schaden erleidet, besteht eine hohe Chance, dass Ihr die Essenz von Gegnern in der Nähe verschlingt, was 2116 Schattenschaden auf sie aufteilt und Euch um 150% des verursachten Schadens heilt.\n\nTödlicher Schaden, der 18656 nicht überschreitet, heilt Euch stattdessen um 20% Eurer Gesundheit und rekonstituiert Euch 6 Sek. lang als instabile Leere. Erreicht 50% Gesundheit, um Euch zu stabilisieren und dem Tod zu entgehen. Dieser Effekt kann einmal pro 8 Min. auftreten. Während der Nukleus sich auflädt, kann der Kern keinen Schaden verursachen." }
entries[1236992] = { ["name"] = "Death Knight Deathbringer 11.2 Class Set 4pc" }
entries[1236993] = { ["name"] = "Energieschild", ["text"] = "Sofort\nWenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern." }
entries[1236996] = { ["name"] = "Ermächtigte Seele", ["text"] = "Sofort\nBlut, Frost, Unheilig\n'Exterminieren' verursacht 20% mehr Schaden und 'Mal des Schnitters' ist bis zu 15-mal zusätzlich stapelbar. Wenn es explodiert, erhöht 'Mal des Schnitters' Eure kritische Trefferchance 8 Sek. lang um 10%." }
entries[1237011] = { ["name"] = "Energiewelle", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern." }
entries[1237032] = { ["name"] = "Tanzende Runenwaffe", ["text"] = "30 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nBeschwört 1 zusätzliche Kopie von 'Tanzende Runenwaffe' und erhöht ihre Dauer um 6 Sek." }
entries[1237033] = { ["name"] = "Geladener Blitz", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was 965 Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern." }
entries[1237036] = { ["name"] = "Geschwader befehligen", ["text"] = "40 Meter Reichweite\nSofort\nWährend Ihr 'Tiefer Atem' wirkt, und bis Abbruch im Anschluss, befehligt Ihr ein Geschwader aus 2 Dracthyr, die Eure Ziele mit 'Desintegrieren' und 'Azurschlag' angreifen." }
entries[1237046] = { ["name"] = "Ausgelaugt", ["text"] = "Sofort\nEnergie entzogen und mit Leere erfüllt." }
entries[1237051] = { ["name"] = "Retten", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nRettet einen ausgelaugten Drachen." }
entries[1237067] = { ["name"] = "Die Jagd", ["text"] = "Unbegrenzte Reichweite\nSofort\nVelaryn markiert einen Spielercharakter als ihre Beute, stürmt auf ihn zu und verursacht 63242239 Chaosschaden. Dieser Effekt wird pro Spielercharakter verringert, der im Weg von ' Die Jagd ' steht.\n\nVelaryn greift außerdem alle Spielercharaktere in ihrer Bahn an und fügt allen Spielercharakteren innerhalb von 3 Metern um jeden getroffenen Spielercharakter 9486336 Chaosschaden zu." }
entries[1237068] = { ["name"] = "Dimensionsatem", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nDie Leerenschwinge entfesselt für 4 Sek. einen galaktischen Strahl aus ihrem Kiefer und fügt allen Spielercharakteren darin alle 0.3 Sek. 30 kosmischen Schaden zu.\n\nMehrere Portale werden aufgerissen, aus denen dieser Atem in zusätzliche Richtungen ausgestrahlt wird." }
entries[1237069] = { ["name"] = "Senken", ["text"] = "Sofort\nIhr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 8 erhöht, bis maximal (12 * 8 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich." }
entries[1237071] = { ["name"] = "Steinfaust", ["text"] = "40 Meter Reichweite\nWirken in 3 sek. 2 sek. Abklingzeit\nKnocks an enemy back.\nInflicts 14546696 Physical damage to an enemy." }
entries[1237072] = { ["name"] = "Flüchtiger Ausstoß", ["text"] = "150 Meter Reichweite\nSofort\nSpeit einen Strom verschlingender Energie, der allen Spielercharakteren in einer Linie von 50 Metern vor dem Zaubernden 30 Gesundheit entzieht. Tropfen fügen Gegnern innerhalb von 5 Metern Schattenschaden zu und hinterlassen 25 Sek. lang ' Verzehrender Speichel '." }
entries[1237074] = { ["name"] = "Flüchtiger Ausstoß", ["text"] = "150 Meter Reichweite\nSofort\nSpeit einen Strom verschlingender Energie, der allen Spielercharakteren in einer Linie von 50 Metern vor dem Zaubernden 30 Gesundheit entzieht. Tropfen fügen Gegnern innerhalb von 5 Metern Schattenschaden zu und hinterlassen 25 Sek. lang ' Verzehrender Speichel '." }
entries[1237079] = { ["name"] = "Gefräßiges Schmettern", ["text"] = "Wirken in 3.5 sek. 4 sek. Abklingzeit\nEntzieht allen Spielercharakteren innerhalb von 12 Metern 50 Gesundheit und überträgt diese auf den Zaubernden." }
entries[1237080] = { ["name"] = "Zerbrochene Welt", ["text"] = "Unbegrenzte Reichweite\nSofort\nFragmente einer von Dimensius zertrümmerten Welt fliegen durch den Raum, fügen getroffenen Spielercharakteren 28107662 kosmischen Schaden zu und werfen sie ab." }
