entries[1237172] = { ["name"] = "Epidemie", ["text"] = "40 Meter Reichweite\nSofort\nLässt jede Eurer virulenten Seuchen aufflammen, wodurch sie dem infizierten Gegner (26.3725% der Angriffskraft) Schattenschaden sowie allen Gegnern in seiner Nähe zusätzlich (10.5491% der Angriffskraft) Schattenschaden zufügen." }
entries[1237173] = { ["name"] = "Infusionsleine", ["text"] = "Unbegrenzte Reichweite\nSofort\nLoom'ithar zieht mehrere Spielercharaktere zu seiner Position und fesselt sie mit seidenen Fäden, die pro Sekunde 452533 Arkanschaden verursachen. Dieser Effekt verstärkt sich mit der Zeit.\n\nJeder Faden reißt, wenn der Abstand 40 Meter beträgt, und hinterlässt an der Position des Spielercharakters einen Fleck ' Lebende Seide '." }
entries[1237184] = { ["name"] = "Splitter des Schicksals", ["text"] = "Wirken in 1.5 sek.\nDie Seelenschreiberin zersplittert die Seele jedes Spielercharakters, beschwört Echos ihres Schicksals und lässt sie 2424449 Arkanschaden erleiden." }
