entries[1237193] = { ["name"] = "Überwältigender Durst", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus teilt die Qual seines unstillbaren Durstes mit seinen Gegnern, was allen Spielercharakteren alle 1 Sek. 20 kosmischen Schaden zufügt, bis sie zugrunde gehen." }
entries[1237195] = { ["name"] = "Bodensturm", ["text"] = "50 Meter Reichweite\nWirken in 4 sek. 4 sek. Abklingzeit\nDer Zaubernde gräbt sich auf sein Ziel zu, stößt es in die Luft und fügt ihm sowie allen Spielercharakteren innerhalb von 10 Metern um das Ziel 4848899 körperlichen Schaden zu." }
entries[1237196] = { ["name"] = "Prügelladung", ["text"] = "Sofort\nPro [(Angriffskraft * 6.25 * (1 + Vielseitigkeit))] Schaden, die Ihr verursacht, wird eine Aufladung von 'Prügelladung' erzeugt. Pro 240 Energie, die Ihr verbraucht, werden alle Aufladungen von 'Prügelladung' entfesselt und verursachen pro Aufladung (60% der Angriffskraft) körperlichen Schaden." }
