entries[1237205] = { ["name"] = "Leerenschritt", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus reißt einen Pfad durch die Leere auf und teleportiert sich an eine andere Position. Spielercharaktere in 4 Metern Entfernung von seinem Pfad zum Ziel erleiden dabei 11243065 kosmischen Schaden.\n\nWährend dieser Bewegung manifestiert Adarus Abbilder von sich selbst, die ' Hungernder Hieb ' wirken." }
