entries[1238266] = { ["name"] = "Ansteigende Kraft", ["text"] = "Sofort\nMit jedem aufeinanderfolgenden Nahkampfangriff auf dasselbe Ziel erhöht sich das Angriffstempo des Zaubernden um 8%.\n\nDieser Effekt ist stapelbar." }
entries[1238269] = { ["name"] = "Ruf der Urahnen", ["text"] = "100 Meter Reichweite\nSofort\n[ Elementar : 'Urzeitliche Welle' ruft für 6 Sek. einen Ahnen an Eure Seite /\n\nWiederherstellung\nDas Profitieren von 'Wogen' ruft für 6 Sek. einen Ahnen an Eure Seite.\n\nDer Einsatz von 'Leben entfesseln' ruft für 12 Sek. einen Ahnen an Eure Seite ]Wann immer Ihr einen Heil- oder Schadenszauber wirkt, wirkt der Ahne einen ähnlichen Zauber." }
