entries[1238285] = { ["name"] = "Shaman Farseer 11.2 Class Set 2pc", ["text"] = "Sofort\nElementar, Verstärkung\nDer Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' 8 Sek. lang um 50%.\n\nWiederherstellung\nDer Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' und 'Springflut' 8 Sek. lang um 50%." }
entries[1238286] = { ["name"] = "Schnelles Ende", ["text"] = "Die Abklingzeit von 'Runenwaffe verstärken' ist um 15 Sek. verringert." }
entries[1238295] = { ["name"] = "Tödliche Absicht", ["text"] = "Der Einsatz von 'Runenwaffe verstärken' verleiht Euch 'Tötungsmaschine'.\n\nTötungsmaschine\nEuer nächster Einsatz von 'Auslöschen' verursacht Frostschaden und ist garantiert ein kritischer Treffer.\n\nEuer nächster Einsatz von 'Frostsichel' ist garantiert ein kritischer Treffer und verursacht das 3-fache des normalen Schadens." }
