entries[1238675] = { ["name"] = "Dämonenseele", ["text"] = "Sofort\nVerwüstung\nDer Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Chaosstoß' während der aktiven Dauer um 20%.\n\nRachsucht\nDer Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Seelenspalter' während der aktiven Dauer um 20%." }
