entries[1238691] = { ["name"] = "Blitzstrom", ["text"] = "50 Meter Reichweite\nSofort\nStößt einen Strahl aus Teufelsenergie aus, der alle 0.3 Sek. 51569735 Feuerschaden verursacht." }
entries[1238693] = { ["name"] = "Leerenglassplitter", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber haben eine Chance, Leerenglassplitter zu beschwören, die Gegner aufschlitzen und ( 474 * 1 ) kosmischen Schaden verursachen, oder Verbündete umkreisen und bis zu 20 Sek. lang 1263 Schaden absorbieren." }
entries[1238696] = { ["name"] = "Dämonenwoge", ["text"] = "Sofort\nDer Zauber 'Metamorphose' [ Verwüstung : lässt 'Dämonenbiss' zusätzlich 15 Jähzorn erzeugen /\n\nRachsucht\nermächtigt 'Seelenspalter' und 'Seelenbombe' stark ]\nWährend die Dämonengestalt aktiv ist, löst der jeweils erste Einsatz jeder ermächtigten Fähigkeit 'Dämonenwoge' aus, wodurch Ihr vor Teufelsenergie explodiert und Gegnern in der Nähe (330% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[1238697] = { ["name"] = "Leerenglasbarriere", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber haben eine Chance, Leerenglassplitter zu beschwören, die Gegner aufschlitzen und ( 474 * 1 ) kosmischen Schaden verursachen, oder Verbündete umkreisen und bis zu 20 Sek. lang 1263 Schaden absorbieren." }
