entries[1238729] = { ["name"] = "Schlackenbasilisk", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Schlackenbasilisken lebten ursprünglich tief unter der Erde und ernährten sich von Obsidian und Basalt. Sie wurden an die Oberfläche gezwungen, als die Legion sie aus ihrer Heimat verdrängte.\"\nWeltereignis:\nWoW Remix: Legion" }
