entries[1238733] = { ["name"] = "Zerschmetterte Seelen", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Töten eines Ziels erzeugt manchmal ein Seelenfragment, das aufgezehrt wird, wenn Ihr Euch nähert. Es heilt Euch um 20% Eurer maximalen Gesundheit .\n\nWenn das Seelenfragment von einem Dämon stammte, wird Euer verursachter Schaden für 15 Sek. um 20% erhöht." }
