entries[1238737] = { ["name"] = "Essenzspalten", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde führt einen nach vorne gerichteten Hieb aus, der allen Spielercharakteren vor ihm 487946 Schattenschaden zufügt. Außerdem wird bei getroffenen Spielercharakteren 348533 Heilung absorbiert." }
