entries[1238751] = { ["name"] = "Infusionsleine", ["text"] = "Unbegrenzte Reichweite\nSofort\nLoom'ithar zieht mehrere Spielercharaktere zu seiner Position und fesselt sie mit seidenen Fäden, die pro Sekunde 452533 Arkanschaden verursachen. Dieser Effekt verstärkt sich mit der Zeit.\n\nJeder Faden reißt, wenn der Abstand 40 Meter beträgt, und hinterlässt an der Position des Spielercharakters einen Fleck ' Lebende Seide '." }
