entries[1239144] = { ["name"] = "Kritischer Abschluss", ["text"] = "Sofort\nFuror, Schutz\nDer Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von [Quellwert]'Schildschlag' um 100%. Kritische Treffer von 'Schildschlag' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%.\n\nWaffen\nDer Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von [Quellwert]'Tödlicher Stoß' um 100%. Kritische Treffer von 'Tödlicher Stoß' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%.\n\n(500ms Abklingzeit)", ["unresolvedValues"] = true }
