entries[1239483] = { ["name"] = "Potentielle Energie", ["text"] = "Sofort\nBraumeister\nWenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [180 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [20 * (500% der Zaubermacht) / 100] heilt.\n\nWindläufer, Nebelwirker\nWenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [20 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [90 * (500% der Zaubermacht) / 100] heilt.\n\n(500ms Abklingzeit)" }
entries[1239486] = { ["name"] = "Breitseite", ["text"] = "100 Meter Reichweite\nSofort\nKapitän Nil'hitan befiehlt seinem Flaggschiff, die Position eines Spielercharakters zu bombardieren, was 871332 kosmischen Schaden verursacht. Das Bombardement verwüstet den Boden und hinterlässt 'Kosmische Wüste', was alle 1 Sek. 104560 kosmischen Schaden verursacht." }
entries[1239487] = { ["name"] = "Bindender Wurfspeer", ["text"] = "100 Meter Reichweite\nSofort\nTaah'bat schleudert arkane Speere auf anvisierte Spielercharaktere, fügt Spielercharakteren innerhalb von 8 Metern um die Ziele 2424449 Arkanschaden zu und fesselt alle getroffenen Spielercharaktere.\n\nJede Fessel verursacht alle 1 Sek. 606112 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%. Die Wirkung verstärkt sich alle 5 Sek., bis der Speer zerstört wird. Dieser Effekt ist stapelbar." }
