entries[1239494] = { ["name"] = "Kosmische Offensive", ["text"] = "100 Meter Reichweite\nSofort\nEure Angriffe haben eine hohe Chance, einen kosmischen Ansturm zu entfesseln, der Eurem Ziel ( 517 * 1 ) kosmischen Schaden zufügt.\n\nDer Schaden wird für jedes Prozent fehlende Gesundheit des Gegners um 2% erhöht und 50% des verursachten Schadens wird auf Gegner in der Nähe aufgeteilt." }
