entries[1239569] = { ["name"] = "Dämonische Intelligenz", ["text"] = "Sofort\nDämonologie\n'Hand von Gul'dan' wird mit voller Macht gewirkt beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu.\n\nGebrechen, Zerstörung\nDer Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu." }
