entries[1239577] = { ["name"] = "Anhaltendes Welken", ["text"] = "Sofort\nGebrechen\nDer Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Gequältes Crescendo' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 25% schneller Schaden verursacht.\n\nDämonologie, Zerstörung\nDer Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Pyrolyse' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 15% schneller Schaden verursacht." }
